function v1320FindDuplicatePlayers(PDO $pdo,string $name,int $excludeId=0): array {
    $name=trim(preg_replace('/\s+/u',' ',$name));if($name==='')return [];
    $q=$pdo->prepare("SELECT p.*,COALESCE((SELECT SUM(sp.games_played) FROM session_players sp WHERE sp.player_id=p.id),0) total_games FROM players p WHERE LOWER(TRIM(p.name))=LOWER(TRIM(?)) AND p.id<>? ORDER BY p.is_active DESC,p.id ASC");
    $q->execute([$name,$excludeId]);return $q->fetchAll();
}
function v1320NicknameAvailable(PDO $pdo,string $name,string $nickname,int $excludeId=0): bool {
    $nickname=trim($nickname);if($nickname==='')return false;
    $q=$pdo->prepare("SELECT COUNT(*) FROM players WHERE LOWER(TRIM(name))=LOWER(TRIM(?)) AND LOWER(TRIM(COALESCE(nickname,'')))=LOWER(TRIM(?)) AND id<>?");$q->execute([trim($name),$nickname,$excludeId]);return (int)$q->fetchColumn()===0;
}
function v1320CreatePlayer(PDO $pdo,string $name,string $nickname,string $gender,string $level='NR',mixed $declaredDupr=null,bool $allowSameNameDifferentNickname=false): int {
    $name=trim(preg_replace('/\s+/u',' ',$name));if($name==='')throw new Exception('Player name is required.');$nickname=trim($nickname);$dups=v1320FindDuplicatePlayers($pdo,$name);
    if($dups){if(!$allowSameNameDifferentNickname)throw new Exception('Duplicate player found. Use the existing player, add a distinguishing nickname for a different person, or discard.');if($nickname==='')throw new Exception('A unique nickname is required for a different player with the same full name.');if(!v1320NicknameAvailable($pdo,$name,$nickname))throw new Exception('That full name + nickname already exists.');}
    if(!in_array($gender,['M','F','Other'],true))$gender='M';$dupr=normalizeDeclaredDupr($declaredDupr);$level=skillLevelFromDupr($dupr,$level);$seed=$dupr??seedRating($level);
    $q=$pdo->prepare("INSERT INTO players(name,nickname,gender,skill_level,dupr_rating,hidden_rating,is_active,updated_at) VALUES(?,?,?,?,?,?,1,NOW())");$q->execute([$name,$nickname,$gender,$level,$dupr,$seed]);return (int)$pdo->lastInsertId();
}

function v1320EnsureQueueOrder(PDO $pdo,int $sessionId): void {
    static $done=[];$key=spl_object_id($pdo).':'.$sessionId;if(isset($done[$key]))return;$done[$key]=true;
    $q=$pdo->prepare("SELECT COALESCE(MAX(queue_credit),0) FROM session_players WHERE session_id=?");$q->execute([$sessionId]);$next=(int)$q->fetchColumn();$q=$pdo->prepare("SELECT id FROM session_players WHERE session_id=? AND queue_credit<=0 ORDER BY id");$q->execute([$sessionId]);$u=$pdo->prepare("UPDATE session_players SET queue_credit=? WHERE id=?");foreach($q->fetchAll() as $r){$next++;$u->execute([$next,(int)$r['id']]);}
}
function v1320NextQueueOrder(PDO $pdo,int $sessionId): int {$q=$pdo->prepare("SELECT COALESCE(MAX(queue_credit),0)+1 FROM session_players WHERE session_id=?");$q->execute([$sessionId]);return max(1,(int)$q->fetchColumn());}
function v1320PlayerRows(PDO $pdo,int $sessionId): array {
    v1320EnsureQueueOrder($pdo,$sessionId);$q=$pdo->prepare("SELECT sp.*,p.name,p.nickname,p.gender,p.skill_level,p.dupr_rating,p.hidden_rating,p.photo_url FROM session_players sp JOIN players p ON p.id=sp.player_id WHERE sp.session_id=? ORDER BY CASE WHEN sp.status='Waiting' THEN 0 ELSE 1 END,sp.queue_credit ASC,sp.id ASC");$q->execute([$sessionId]);return $q->fetchAll();
}
function v1320GenerateOnDeck(PDO $pdo,int $sessionId): ?int {
    $q=$pdo->prepare("SELECT id FROM matches WHERE session_id=? AND status='ondeck' LIMIT 1");$q->execute([$sessionId]);if($q->fetch())return null;
    $eligible=array_values(array_filter(v1320PlayerRows($pdo,$sessionId),fn($p)=>$p['status']==='Waiting'));if(count($eligible)<4)return null;
    $four=array_slice($eligible,0,4);[$partners,$opponents]=recentPairs($pdo,$sessionId);$options=pairingCandidates($four,$partners,$opponents);$pick=weightedRandomMatch($options)??($options[0]??null);if(!$pick)return null;
    $q=$pdo->prepare("INSERT INTO matches(session_id,court_no,status,a1,a2,b1,b2) VALUES(?,1,'ondeck',?,?,?,?)");$q->execute([$sessionId,$pick['A'][0]['player_id'],$pick['A'][1]['player_id'],$pick['B'][0]['player_id'],$pick['B'][1]['player_id']]);return (int)$pdo->lastInsertId();
}
function v1320StartOnDeck(PDO $pdo,int $sessionId): void {
    $q=$pdo->prepare("SELECT id FROM matches WHERE session_id=? AND status='active' LIMIT 1");$q->execute([$sessionId]);if($q->fetch())return;$q=$pdo->prepare("SELECT * FROM matches WHERE session_id=? AND status='ondeck' ORDER BY id LIMIT 1");$q->execute([$sessionId]);$m=$q->fetch();if(!$m)return;
