}
function v1320InitializeQueue(PDO $pdo,int $sessionId): void {v1320EnsureQueueOrder($pdo,$sessionId);v1320GenerateOnDeck($pdo,$sessionId);v1320StartOnDeck($pdo,$sessionId);v1320GenerateOnDeck($pdo,$sessionId);}
function v1320CheckInPlayer(PDO $pdo,int $sessionId,int $playerId): void {
    addRosterPlayer($pdo,$sessionId,$playerId);$order=v1320NextQueueOrder($pdo,$sessionId);$q=$pdo->prepare("INSERT INTO session_players(session_id,player_id,status,queue_credit,games_since_last_played) VALUES(?,?,'Waiting',?,0) ON DUPLICATE KEY UPDATE queue_credit=IF(status='Checked Out',VALUES(queue_credit),queue_credit),status=IF(status='Checked Out','Waiting',status)");$q->execute([$sessionId,$playerId,$order]);v1320GenerateOnDeck($pdo,$sessionId);v1320StartOnDeck($pdo,$sessionId);v1320GenerateOnDeck($pdo,$sessionId);
